            var loggerMock = new Mock<ILogger>();
            var migrationSession = new MigrateSession(loggerMock.Object);

            // Act
            await migrationSession.MigrateSlotsDriverInlineAsync();

            // Assert
            loggerMock.Verify(l => l.LogError(It.IsAny<string>()), Times.Once);
        }

